mapper.select:
select u.id, u.nickname, u.avatar,
uf.create_time cursor_time,
uf.id cursor_id
from user_follow uf
join user u on uf.followee_id = u.id
where uf.follower_id = #{userId}

    and ( uf.create_time < #{cursorTime}
    or (uf.create_time = #{cursorTime} and uf.id < #{cursorId}) )

order by uf.create_time desc, uf.id desc
limit #{size}
